 "content": "def transform(grid):
    g = [list(row) for row in grid]
    h, w = len(g), len(g[0])
    # A solid colored edge line is the stop wall; objects move toward it.
    if len(set(g[0])) == 1 and g[0][0] != 0:
        direction = -1
        wall = {(0, c) for c in range(w)}
    elif len(set(g[-1])) == 1 and g[-1][0] != 0:
        direction = 1
        wall = {(h - 1, c) for c in range(w)}
    else:
        raise ValueError('expected a solid edge wall')

    seen = set(wall)
    objects = []
    for r in range(h):
        for c in range(w):
            if g[r][c] == 0 or (r, c) in seen:
                continue
            color = g[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and g[nr][nc] == color:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            objects.append((color, cells))

    # Process pieces nearest the wall first, so they settle before pieces behind them.
    if direction > 0:
        objects.sort(key=lambda obj: max(r for r, _ in obj[1]), reverse=True)
    else:
        objects.sort(key=lambda obj: min(r for r, _ in obj[1]))

    occupied = set(wall)
    for color, cells in objects:
        for r, c in cells:
            g[r][c] = 0
        shifted = list(cells)
        while True:
            candidate = [(r + direction, c) for r, c in shifted]
            if any(r < 0 or r >= h or c < 0 or c >= w or (r, c) in occupied for r, c in candidate):
                break
            shifted = candidate
        for r, c in shifted:
            g[r][c] = color
            occupied.add((r, c))
    return g
